def fresh_unit(name="Unit 1"):
    u = {"unit_name":name}
    for _,key,_,_ in UNIT_PARAM_ROWS:
        u[key] = None
    return u

def init():
    defs = {"project":fresh_project(),"page":"project","results":[],
            "dca_params":{"q0":None,"Di_annual":None,"b":0.0,"cod_date":date.today(),
                          "max_years":30,"install_cap":None,"threshold_pct":90.0,
                          "mu_output":None,"mu_success":80.0,"mu_decline_rate":None,
                          "mu_schedule_mode":"auto","mu_manual_years":[],"mu_max_wells":20},
            "dca_results":None,"well_schedule":[]}
    for k,v in defs.items():
        if k not in st.session_state: st.session_state[k]=v
init()

def P(): return st.session_state["project"]
def ensure_units():
    p=P(); n=p["n_units"] or 1
    while len(p["units"])<n:
        p["units"].append(fresh_unit(f"Unit {len(p['units'])+1}"))
    p["units"]=p["units"][:n]

def sf(v,d=0.0):
    try: return float(v) if v is not None else None
    except: return None

def pct_to_dec(v):
    """Convert % input to decimal, handle both cases"""
    if v is None: return None
    return float(v)/100 if float(v)>1 else float(v)

