def page_project():
    tab_new, tab_open = st.tabs(["➕ Create / Edit Project","📂 Open Existing Project"])

    with tab_new:
        p = P()
        col_left, col_map = st.columns([3,2])

        with col_left:
            # ── Basic Info ────────────────────────────────────────────────────
            st.markdown('<div class="panel"><div class="panel-title">📌 Project Information</div>', unsafe_allow_html=True)
            c1,c2,c3 = st.columns(3)
            with c1:
                p["project_name"] = st.text_input("Project Name *", value=p.get("project_name","") or "", placeholder="e.g. LHD Binary")
                p["field_name"]   = st.text_input("Field / WKP", value=p.get("field_name","") or "", placeholder="e.g. Lahendong")
            with c2:
                p["start_year"]    = st.number_input("Model Start Year",2015,2040,value=int(p["start_year"]) if p.get("start_year") else None, placeholder="e.g. 2026")
                p["model_horizon"] = st.number_input("Model Horizon (yr)",10,60,value=int(p["model_horizon"]) if p.get("model_horizon") else None, placeholder="e.g. 40")
            with c3:
                p["n_units"] = st.number_input("Number of Units",1,10,value=int(p["n_units"]) if p.get("n_units") else 1,
                                help="Each unit = independent development unit with own CAPEX/OPEX/tariff")
                p["lat"] = st.number_input("Latitude", -90.0,90.0, value=float(p["lat"]) if p.get("lat") else None,
                            format="%.4f", placeholder="e.g. 1.3030")
                p["lon"] = st.number_input("Longitude",-180.0,180.0,value=float(p["lon"]) if p.get("lon") else None,
                            format="%.4f", placeholder="e.g. 124.797")
            st.markdown("</div>", unsafe_allow_html=True)

            # ── Financial & Tax (shared – 1 set for all units) ────────────────
            st.markdown('<div class="panel"><div class="panel-title">💼 Financial & Tax (Applied to All Units)</div>', unsafe_allow_html=True)
            f1,f2,f3,f4 = st.columns(4)
            def pct_field(label, key, placeholder, col, fmt="%.3f", maxv=100.0):
                v = p.get(key)
                val = col.number_input(label,0.0,maxv,
                       value=float(v)*100 if v and float(v)<=1 else float(v) if v else None,
                       placeholder=placeholder, key=f"proj_{key}", format=fmt)
                p[key] = val/100 if val is not None else None
            def num_field(label, key, placeholder, col, fmt="%.2f", maxv=1e7):
                v = p.get(key)
                val = col.number_input(label,0.0,maxv,
                       value=float(v) if v else None,
                       placeholder=placeholder, key=f"proj_{key}", format=fmt)
                p[key] = val
            pct_field("Hurdle Rate/WACC (%)","hurdle_rate","e.g. 7.71",f1)
            pct_field("Cost Escalation (%/yr)","cost_esc_rate","e.g. 2.36",f2)
            pct_field("PPh Badan (%)","corp_tax_rate","e.g. 22",f3)
            pct_field("VAT (%)","vat","e.g. 11",f4)
            f5,f6,f7,f8 = st.columns(4)
            pct_field("Production Fee (% Rev)","production_fee_pct","e.g. 2.5",f5)
            pct_field("Production Bonus (% Rev)","production_bonus_pct","e.g. 0.5",f6)
            num_field("Base IDR/USD Rate","base_idr_usd","e.g. 16500",f7,fmt="%.0f",maxv=1e6)
            v_con = p.get("concessional_treatment","Kuasa Pengusahaan")
            p["concessional_treatment"] = f8.selectbox("Concessional Treatment",
                ["Kuasa Pengusahaan","IUP","IUPK","PKP2B"],
                index=["Kuasa Pengusahaan","IUP","IUPK","PKP2B"].index(v_con) if v_con in ["Kuasa Pengusahaan","IUP","IUPK","PKP2B"] else 0,
                key="proj_concess")
            st.markdown("</div>", unsafe_allow_html=True)

            # ── Depreciation ───────────────────────────────────────────────────
            st.markdown('<div class="panel"><div class="panel-title">📉 Depreciation Assumptions</div>', unsafe_allow_html=True)
            d1,d2,d3,d4 = st.columns(4)
            dep_methods = ["Straight Line","Declining Balance"]
            dep_m = p.get("dep_method","Straight Line")
            p["dep_method"] = d1.selectbox("Method",dep_methods,
                index=dep_methods.index(dep_m) if dep_m in dep_methods else 0, key="proj_dep_method")
            v2 = p.get("dep_declining_pct")
            p["dep_declining_pct"] = d2.number_input("Declining Balance (%)",0.0,100.0,
                value=float(v2)*100 if v2 and float(v2)<=1 else float(v2) if v2 else None,
                placeholder="e.g. 25", key="proj_ddp") 
            v3 = p.get("dep_years_wells")
            p["dep_years_wells"] = d3.number_input("Wells & Infra Dep (yr)",1,50,
                value=int(v3) if v3 else None, placeholder="e.g. 20", key="proj_dyw")
            v4 = p.get("dep_years_pp")
            p["dep_years_pp"] = d4.number_input("Power Plant Dep (yr)",1,50,
                value=int(v4) if v4 else None, placeholder="e.g. 25", key="proj_dypp")
            e1,e2 = st.columns(2)
            v5 = p.get("dep_years_sags")
            p["dep_years_sags"] = e1.number_input("SAGS Dep (yr)",1,50,
                value=int(v5) if v5 else None, placeholder="e.g. 15", key="proj_dys")
            v6 = p.get("tax_loss_carryforward_yrs")
            p["tax_loss_carryforward_yrs"] = e2.number_input("Tax Loss Carryforward (yr)",0,10,
                value=int(v6) if v6 else 5, key="proj_tlcf")
            st.markdown("</div>", unsafe_allow_html=True)

            # ── Exploration Phase (shared) ─────────────────────────────────────
            st.markdown('<div class="panel"><div class="panel-title">🔍 Exploration Phase CAPEX (Shared – Not per Unit)</div>', unsafe_allow_html=True)
            ex1,ex2,ex3,ex4 = st.columns(4)
            def exp_num(label, key, placeholder, col):
                v = p.get(key)
                val = col.number_input(label,0.0,1e7,
                       value=float(v) if v else None,
                       placeholder=placeholder, key=f"proj_{key}", format="%.1f")
                p[key] = val
            exp_num("G&A Exploration (kUSD/yr)","ga_exploration","e.g. 181",ex1)
            exp_num("Survey 4G (kUSD)","survey_4g","e.g. 24",ex2)
            exp_num("Land & Infra Exploration (kUSD)","land_infra_exploration","e.g. 5,518",ex3)
            exp_num("Well Cost per Well (kUSD)","exploration_well_cost","e.g. 8,462",ex4)
            ex5,ex6,ex7,ex8 = st.columns(4)
            v_nw = p.get("n_exploration_wells")
            p["n_exploration_wells"] = ex5.number_input("# Exploration Wells",0,20,
                value=int(v_nw) if v_nw else None, placeholder="e.g. 2", key="proj_nexpw")
            v_sr = p.get("success_ratio_exploration")
            p["success_ratio_exploration"] = ex6.number_input("Success Ratio (%)",0.0,100.0,
                value=float(v_sr)*100 if v_sr and float(v_sr)<=1 else float(v_sr) if v_sr else None,
                placeholder="e.g. 83", key="proj_sr", format="%.1f")
            exp_num("Well Testing Exploration (kUSD)","well_testing_exploration","e.g. 0",ex7)
            exp_num("Exploration Fixed Fee (kUSD)","exploration_fixed_fee","e.g. 0",ex8)
            st.markdown("</div>", unsafe_allow_html=True)

            # ── Loans ──────────────────────────────────────────────────────────
            with st.expander("🏦 Loan Assumptions – Exploration", expanded=False):
                loan_tab_fields = [
                    ("Principal (kUSD)","exp_loan_principal","%.1f"),
                    ("Start Year","exp_loan_start_year","%.0f"),
                    ("Repayment Years","exp_loan_repay_years","%.0f"),
                    ("Grace Period (yr)","exp_loan_grace_period","%.0f"),
                    ("Interest Rate (%)","exp_loan_interest_rate","%.3f"),
                    ("Front-End Fee (%)","exp_loan_front_end_fee","%.3f"),
                    ("Commitment Fee (%)","exp_loan_commitment_fee","%.3f"),
                ]
                lc = st.columns(len(loan_tab_fields))
                for (lbl,key,fmt),col in zip(loan_tab_fields,lc):
                    v = p.get(key)
                    is_pct = "Rate" in lbl or "Fee" in lbl
                    disp = float(v)*100 if v and is_pct and float(v)<=1 else float(v) if v else None
                    val = col.number_input(lbl,0.0,1e7,value=disp,placeholder="—",
                           key=f"proj_{key}",format=fmt)
                    p[key] = (val/100 if is_pct and val and val>1 else val)

            with st.expander("🏦 Loan Assumptions – Development Upstream", expanded=False):
                fields_up = [
                    ("Principal (kUSD)","dev_upstream_loan_principal","%.1f"),
                    ("Start Year","dev_upstream_loan_start_year","%.0f"),
                    ("Repayment Years","dev_upstream_repay_years","%.0f"),
                    ("Grace Period (yr)","dev_upstream_grace_period","%.0f"),
                    ("Interest Rate (%)","dev_upstream_interest_rate","%.3f"),
                    ("Front-End Fee (%)","dev_upstream_front_end_fee","%.3f"),
                    ("Commitment Fee (%)","dev_upstream_commitment_fee","%.3f"),
                ]
                lc2 = st.columns(len(fields_up))
                for (lbl,key,fmt),col in zip(fields_up,lc2):
                    v = p.get(key)
                    is_pct = "Rate" in lbl or "Fee" in lbl
                    disp = float(v)*100 if v and is_pct and float(v)<=1 else float(v) if v else None
                    val = col.number_input(lbl,0.0,1e7,value=disp,placeholder="—",
                           key=f"proj_{key}",format=fmt)
                    p[key] = (val/100 if is_pct and val and val>1 else val)

            with st.expander("🏦 Loan Assumptions – Development Downstream (Corp Loan)", expanded=False):
                fields_dn = [
                    ("Principal (kUSD)","dev_downstream_loan_principal","%.1f"),
                    ("Start Year","dev_downstream_loan_start_year","%.0f"),
                    ("Repayment Years","dev_downstream_repay_years","%.0f"),
                    ("Grace Period (yr)","dev_downstream_grace_period","%.0f"),
                    ("Interest Rate (%)","dev_downstream_interest_rate","%.3f"),
                    ("Front-End Fee (%)","dev_downstream_front_end_fee","%.3f"),
                    ("Commitment Fee (%)","dev_downstream_commitment_fee","%.3f"),
                ]
                lc3 = st.columns(len(fields_dn))
                for (lbl,key,fmt),col in zip(fields_dn,lc3):
                    v = p.get(key)
                    is_pct = "Rate" in lbl or "Fee" in lbl
                    disp = float(v)*100 if v and is_pct and float(v)<=1 else float(v) if v else None
                    val = col.number_input(lbl,0.0,1e7,value=disp,placeholder="—",
                           key=f"proj_{key}",format=fmt)
                    p[key] = (val/100 if is_pct and val and val>1 else val)

        with col_map:
            # ── Interactive Map ────────────────────────────────────────────────
            st.markdown('<div class="sec">🗺️ PGE Field Map</div>', unsafe_allow_html=True)
            m = folium.Map(location=[-2.5,118], zoom_start=5, tiles="CartoDB positron")
            for f in PGE_FIELDS:
                folium.CircleMarker(location=[f["lat"],f["lon"]], radius=8,
                    color="#3182ce", fill=True, fill_color="#3182ce", fill_opacity=0.7,
                    tooltip=f"{f['name']} · {f['cap']} MW",
                    popup=folium.Popup(f"<b>{f['name']}</b><br>{f['cap']} MW", max_width=180)
                ).add_to(m)
                folium.Marker(location=[f["lat"],f["lon"]],
                    icon=folium.DivIcon(html=f'<div style="font-size:8px;color:#2b6cb0;font-weight:700;white-space:nowrap;margin-top:10px">{f["name"]}</div>')).add_to(m)
            if p.get("lat") and p.get("lon"):
                res_list = st.session_state.get("results",[])
                npv_str = ""
                if res_list:
                    tnpv = sum(r.get("npv_ufcf",0) for r in res_list)
                    npv_str = f"<br>NPV: {tnpv/1000:,.1f} M USD"
                popup_html = f"<b>📁 {p['project_name']}</b><br>{p.get('field_name','')}<br>{p['n_units']} unit(s){npv_str}"
                folium.Marker(location=[p["lat"],p["lon"]],
                    popup=folium.Popup(popup_html,max_width=200),
                    tooltip=f"📁 {p['project_name']}",
                    icon=folium.Icon(color="red",icon="star",prefix="fa")).add_to(m)
            st_folium(m, width=None, height=360, key="proj_map")

        st.markdown("---")
        c1,c2 = st.columns([3,1])
        with c1:
            if st.button("✅ Save Project Settings", type="primary", use_container_width=True):
                ensure_units()
                save_project(P())
                st.success(f"✅ Project '{p['project_name']}' saved!")
        with c2:
            if st.button("🗑️ Reset Project", use_container_width=True):
                st.session_state["project"] = fresh_project()
                st.session_state["results"] = []
                st.rerun()

    with tab_open:
        projects = list_projects()
        if not projects:
            st.info("📭 No saved projects found.")
        for p_ in projects:
            c1,c2,c3 = st.columns([5,1,1])
            with c1:
                st.markdown(f"""<div class="panel" style="margin-bottom:6px">
                  <b style="color:#2b6cb0">📁 {p_['name']}</b>
                  <span style="font-size:11px;color:#718096;margin-left:10px">{p_['n_units']} unit(s) · {p_['modified']}</span>
                </div>""", unsafe_allow_html=True)
            with c2:
                st.write("")
                if st.button("📂",key=f"op_{p_['file']}",use_container_width=True,help="Open"):
                    data=load_project(p_["file"])
                    st.session_state["project"]=data
                    st.session_state["results"]=[]
                    st.success(f"Loaded: {p_['name']}"); st.rerun()
            with c3:
                st.write("")
                if st.button("🗑️",key=f"dl_{p_['file']}",use_container_width=True,help="Delete"):
                    delete_project(p_["file"]); st.rerun()
        st.markdown("---")
        uploaded=st.file_uploader("⬆️ Upload Project JSON",type=["json"])
        if uploaded:
            try:
                data=json.load(uploaded)
                st.session_state["project"]=data
                st.session_state["results"]=[]
                st.success(f"Loaded: {data.get('project_name','')}")
            except Exception as e: st.error(f"Failed: {e}")


# ══════════════════════════════════════════════════════════════════════════════
# PAGE: WELL SCHEDULING
# ══════════════════════════════════════════════════════════════════════════════
def page_well_scheduling():
    p = P(); ensure_units()
    ws_list = st.session_state.get("well_schedule", [])

    col_inp, col_chart = st.columns([2,3])
    with col_inp:
        st.markdown('<div class="panel"><div class="panel-title">⚙️ Well Schedule Settings</div>', unsafe_allow_html=True)
        mode = st.radio("Schedule Mode",["✋ Manual Entry","🤖 Auto (DCA-based)"],
                        horizontal=True, key="ws_mode")
        sy = int(p.get("start_year") or 2026)
        mh = int(p.get("model_horizon") or 40)

        if "✋" in mode:
            st.markdown("**Add Well Entry**")
            wa1,wa2 = st.columns(2)
            w_year = wa1.number_input("Onstream Year",sy,sy+mh-1,sy,1,key="ws_yr")
            w_type = wa2.selectbox("Well Type",
                ["Exploration Well","Well Testing Exploration",
                 "Production Well","Injection Well",
                 "Makeup Well","Workover/Hole Cleaning"],key="ws_type")
            wa3,wa4,wa5 = st.columns(3)
            w_unit = wa3.selectbox("Unit",[u.get("unit_name",f"Unit {i+1}") for i,u in enumerate(p["units"])]+["Exploration (Shared)"],key="ws_unit")
            w_mw   = wa4.number_input("Output (MW)",0.0,200.0,value=None,placeholder="e.g. 10",key="ws_mw",format="%.2f")
            w_name = wa5.text_input("Well Name",placeholder=f"e.g. P-{len(ws_list)+1}",key="ws_name")
            if st.button("➕ Add Well",type="primary",use_container_width=True,key="ws_add"):
                ws_list.append({"year":int(w_year),"type":w_type,"unit":w_unit,
                                "mw_output":float(w_mw) if w_mw else 0,
                                "name":w_name or f"Well-{len(ws_list)+1}"})
                st.session_state["well_schedule"]=ws_list
                st.rerun()

        else:  # Auto DCA
            dp = st.session_state["dca_params"]
            st.markdown("**DCA Parameters for Auto Schedule**")
            da1,da2 = st.columns(2)
            dp["install_cap"] = da1.number_input("Install Capacity (MW)",0.0,500.0,
                value=float(dp["install_cap"]) if dp.get("install_cap") else None,
                placeholder="e.g. 30",key="ws_dcacap")
            dp["q0"] = da2.number_input("Initial Production at COD (MW)",0.0,500.0,
                value=float(dp["q0"]) if dp.get("q0") else None,
                placeholder="e.g. 33",key="ws_dcaq0")
            db1,db2,db3 = st.columns(3)
            dp["Di_annual"] = db1.number_input("Decline Rate (%/yr)",0.0,50.0,
                value=float(dp["Di_annual"])*100 if dp.get("Di_annual") else None,
                placeholder="e.g. 3.0",key="ws_dcadi")
            if dp.get("Di_annual") and dp["Di_annual"]>0.5: dp["Di_annual"]/=100
            b_sel = db2.selectbox("Decline Type",["Exponential (b=0)","Hyperbolic","Harmonic (b=1)"],key="ws_btype")
            dp["b"] = 0.0 if "Exp" in b_sel else (1.0 if "Harm" in b_sel else
                db3.number_input("b value",0.0,1.0,0.3,0.05,key="ws_bval"))
            dp["threshold_pct"] = st.number_input("MU Trigger Threshold (% of Cap)",50.0,100.0,90.0,1.0,key="ws_thr")
            dp["mu_output"] = st.number_input("Output per MU Well (MW)",0.0,100.0,
                value=float(dp["mu_output"]) if dp.get("mu_output") else None,
                placeholder="e.g. 10",key="ws_muout")
            dp["mu_success"] = st.number_input("MU Success Ratio (%)",0.0,100.0,80.0,1.0,key="ws_musr")
            dp["mu_max_wells"] = st.number_input("Max MU Wells",0,50,int(dp.get("mu_max_wells",20)),key="ws_mumax")
            cod_v = p["units"][0].get("cod_date") if p["units"] else None
            if isinstance(cod_v,str):
                try: cod_v=date.fromisoformat(cod_v)
                except: cod_v=date.today()
            dp["cod_date"] = cod_v or date.today()
            dp["max_years"] = int(p.get("model_horizon") or 30)

            if st.button("🤖 Generate Auto MU Schedule",type="primary",use_container_width=True,key="ws_autogen"):
                if dp.get("q0") and dp.get("Di_annual") and dp.get("install_cap"):
                    dp2 = dict(dp)
                    dp2["mu_decline_rate"] = dp2.get("mu_decline_rate") or dp2["Di_annual"]
                    dp2["mu_output"] = dp2.get("mu_output") or 10.0
                    res_dca = run_dca(dp2)
                    st.session_state["dca_results"] = res_dca
                    # Convert DCA makeup schedule to well schedule
                    for mu in res_dca["mu_schedule"]:
                        ws_list.append({"year":mu["Year"],"type":"Makeup Well",
                                        "unit":p["units"][0].get("unit_name","Unit 1") if p["units"] else "Unit 1",
                                        "mw_output":mu["MW Added"],"name":f"MU Well #{mu['Cumulative Wells']}"})
                    st.session_state["well_schedule"]=ws_list
                    st.success(f"✅ {len(res_dca['mu_schedule'])} makeup wells scheduled!")
                else:
                    st.error("Fill q0, Di_annual, install_cap first")

        st.markdown("</div>",unsafe_allow_html=True)

        # Well schedule table
        if ws_list:
            st.markdown('<div class="sec">📋 Well Schedule</div>',unsafe_allow_html=True)
            df_ws = pd.DataFrame(ws_list)
            st.dataframe(df_ws,use_container_width=True,hide_index=False,height=300)
            c1,c2 = st.columns(2)
            with c1:
                if st.button("🗑️ Clear All Wells",use_container_width=True):
                    st.session_state["well_schedule"]=[]
                    st.rerun()
            with c2:
                del_idx = st.number_input("Delete row #",0,max(len(ws_list)-1,0),0,key="ws_delidx")
                if st.button("🗑️ Delete Row",use_container_width=True,key="ws_delrow"):
                    ws_list.pop(int(del_idx))
                    st.session_state["well_schedule"]=ws_list
                    st.rerun()

    with col_chart:
        st.markdown('<div class="sec">📊 Well Onstream Timeline</div>',unsafe_allow_html=True)
        if not ws_list:
            st.info("Add wells to see the timeline chart.")
        else:
            df_ws = pd.DataFrame(ws_list)
            # Gantt-style chart
            type_colors = {
                "Exploration Well":"#e53e3e","Well Testing Exploration":"#ed8936",
                "Production Well":"#38a169","Injection Well":"#3182ce",
                "Makeup Well":"#805ad5","Workover/Hole Cleaning":"#718096"
            }
            fig = go.Figure()
            for wt, grp in df_ws.groupby("type"):
                color = type_colors.get(wt,"#4a5568")
                fig.add_trace(go.Scatter(
                    x=grp["year"],
                    y=grp["name"] if "name" in grp.columns else [f"Well-{j}" for j in grp.index],
                    mode="markers+text",
                    marker=dict(symbol="diamond",size=14,color=color,
                                line=dict(width=1,color="white")),
                    text=[f" {r.get('mw_output',0):.1f} MW" for _,r in grp.iterrows()],
                    textposition="middle right",textfont=dict(size=9),
                    name=wt, marker_color=color
                ))
            fig.update_layout(height=380,title="Well Onstream Timeline",
                plot_bgcolor="#fff",paper_bgcolor="#fff",
                xaxis=dict(title="Year",gridcolor="#edf2f7",dtick=2),
                yaxis=dict(title=""),showlegend=True,
                legend=dict(orientation="h",y=-0.2,x=0),
                margin=dict(l=10,r=10,t=40,b=60),font=dict(size=10))
            st.plotly_chart(fig,use_container_width=True,key="ws_timeline")

            # Summary by type
            st.markdown('<div class="sec">📈 Cumulative Wells by Year</div>',unsafe_allow_html=True)
            sy2 = int(p.get("start_year") or 2026)
            mh2 = int(p.get("model_horizon") or 40)
            years2 = list(range(sy2, sy2+mh2))
            well_counts = {wt:[0]*len(years2) for wt in type_colors}
            for ws in ws_list:
                wt = ws.get("type","Makeup Well")
                yr = ws.get("year",sy2)
                if yr in years2:
                    idx = years2.index(yr)
                    if wt in well_counts:
                        well_counts[wt][idx] += 1
            fig2 = go.Figure()
            for wt,counts in well_counts.items():
                if any(c>0 for c in counts):
                    cum = np.cumsum(counts).tolist()
                    fig2.add_trace(go.Scatter(x=years2,y=cum,name=wt,
                        line=dict(color=type_colors.get(wt,"#4a5568"),width=2),
                        stackgroup="wells",fill="tonexty"))
            fig2.update_layout(height=220,plot_bgcolor="#fff",paper_bgcolor="#fff",
                xaxis=dict(gridcolor="#edf2f7"),yaxis=dict(title="Cumulative Wells"),
                title="Cumulative Well Count",margin=dict(l=5,r=5,t=40,b=5),font=dict(size=10))
            st.plotly_chart(fig2,use_container_width=True,key="ws_cumwells")


# ══════════════════════════════════════════════════════════════════════════════
# PAGE: INPUT PARAMETERS (matrix: rows=params, cols=units, freeze left col)
# ══════════════════════════════════════════════════════════════════════════════
def page_input():
    p = P(); ensure_units()
    n_units = p["n_units"] or 1
    units   = p["units"]
    sy = int(p.get("start_year") or 2026)
    mh = int(p.get("model_horizon") or 40)

    # Group params by category
    cats = {}
    for row in UNIT_PARAM_ROWS:
        lbl,key,unit_str,cat = row
        cats.setdefault(cat,[]).append(row)

    st.markdown("""
    <style>
    .param-matrix{width:100%;border-collapse:collapse;font-size:12px;}
    .param-matrix th{background:#1a5276;color:#fff;padding:6px 10px;
      text-align:center;white-space:nowrap;position:sticky;top:0;z-index:2;}
    .param-matrix th:first-child{text-align:left;min-width:200px;
      position:sticky;left:0;z-index:3;background:#0d3b6e;}
    .param-matrix th:nth-child(2){min-width:60px;position:sticky;left:0;z-index:2;}
    .param-matrix td{padding:3px 6px;border:1px solid #e2e8f0;vertical-align:middle;}
    .param-matrix td:first-child{background:#f7fafc;font-weight:600;color:#2d3748;
      position:sticky;left:0;z-index:1;min-width:200px;}
    .param-matrix td:nth-child(2){background:#f7fafc;color:#718096;font-size:11px;
      text-align:center;}
    .cat-header td{background:#2c3e50!important;color:#fff!important;
      font-weight:700!important;padding:6px 10px!important;}
    </style>""", unsafe_allow_html=True)

    # ── Spending Schedule toggle ───────────────────────────────────────────────
    show_spend = st.toggle("📅 Show Annual Spending Schedule", value=False, key="show_spend")

    # ── Build input matrix with Streamlit widgets ──────────────────────────────
    for cat, rows in cats.items():
        st.markdown(f'<div class="sec">{CAT_LABELS[cat]}</div>', unsafe_allow_html=True)

        # Header row
        unit_names = [u.get("unit_name") or f"Unit {i+1}" for i,u in enumerate(units)]
        hdr_cols = st.columns([3,1]+[2]*n_units)
        hdr_cols[0].markdown("**Parameter**")
        hdr_cols[1].markdown("**Unit**")
        for ci, uname in enumerate(unit_names):
            hdr_cols[ci+2].markdown(f"**{uname}**")

        for lbl,key,unit_str,_ in rows:
            row_cols = st.columns([3,1]+[2]*n_units)
            row_cols[0].markdown(f"<div style='padding:4px 0;font-size:12px;color:#2d3748'>{lbl}</div>",
                                 unsafe_allow_html=True)
            row_cols[1].markdown(f"<div style='padding:4px 0;font-size:11px;color:#718096;text-align:center'>{unit_str}</div>",
                                 unsafe_allow_html=True)
            for ui, u in enumerate(units):
                with row_cols[ui+2]:
                    cur = u.get(key)
                    wkey = f"inp_{ui}_{key}"
                    if key == "scheme":
                        val = st.selectbox("",["PJBL","PJBU","CA"],
                              index=["PJBL","PJBU","CA"].index(cur) if cur in ["PJBL","PJBU","CA"] else 0,
                              key=wkey, label_visibility="collapsed")
                        u[key] = val
                    elif key == "cod_date":
                        cod_v = cur
                        if isinstance(cod_v,str):
                            try: cod_v=date.fromisoformat(cod_v)
                            except: cod_v=None
                        val = st.date_input("",value=cod_v,format="DD/MM/YYYY",
                              key=wkey, label_visibility="collapsed")
                        u[key] = val
                    elif unit_str in ["yr","Well"] or key in ["n_prod_wells","n_inj_wells",
                            "n_makeup_wells","major_overhaul_interval","minor_overhaul_interval",
                            "dev_years_ga","lifetime"]:
                        val = st.number_input("",0,999,
                              value=int(cur) if cur is not None else None,
                              placeholder="—",key=wkey,label_visibility="collapsed")
                        u[key] = val
                    elif unit_str == "%":
                        disp = float(cur)*100 if cur and float(cur)<=1 else float(cur) if cur else None
                        val = st.number_input("",0.0,100.0,value=disp,
                              placeholder="—",key=wkey,format="%.2f",label_visibility="collapsed")
                        u[key] = (val/100) if val is not None else None
                    elif unit_str == "%/yr":
                        disp = float(cur)*100 if cur and float(cur)<=1 else float(cur) if cur else None
                        val = st.number_input("",0.0,100.0,value=disp,
                              placeholder="—",key=wkey,format="%.3f",label_visibility="collapsed")
                        u[key] = (val/100) if val is not None else None
                    else:
                        # kUSD fields with $ prefix via format
                        val = st.number_input("",0.0,1e7,
                              value=float(cur) if cur else None,
                              placeholder="—",key=wkey,format="%.1f",label_visibility="collapsed")
                        u[key] = val

        st.markdown("---")

    # ── Annual Spending Schedule ───────────────────────────────────────────────
    if show_spend:
        st.markdown('<div class="sec">📅 Annual Spending Schedule (kUSD per year)</div>', unsafe_allow_html=True)
        spend_items = [
            "GA Exploitation","Land & Infra Exploitation","FEED Cost","FCRS Cost",
            "Power Plant Cost","Transmission Cost","Production Well Cost",
            "Injection Well Cost","IDC","Makeup Well Cost","Infrastructure Makeup","FCRS Makeup",
        ]
        years_list = list(range(sy, sy+mh))
        # Show only first 20 years for readability, user can see full in export
        show_yrs = years_list[:20]

        for ui, u in enumerate(units):
            uname = u.get("unit_name") or f"Unit {ui+1}"
            with st.expander(f"⚡ {uname} – Spending Schedule", expanded=False):
                ss = u.setdefault("spending_schedule", {str(yr):{} for yr in years_list})
                # Build editable df
                rows_data = {}
                for item in spend_items:
                    rows_data[item] = [float(ss.get(str(yr),{}).get(item,0) or 0) for yr in show_yrs]
                df_spend = pd.DataFrame(rows_data, index=[str(y) for y in show_yrs]).T
                df_spend.columns = [str(y) for y in show_yrs]

                edited = st.data_editor(df_spend, use_container_width=True,
                                        key=f"spend_{ui}",
                                        num_rows="fixed")
                # Save back
                for yr_str in edited.columns:
                    ss.setdefault(yr_str,{})
                    for item in spend_items:
                        ss[yr_str][item] = float(edited.loc[item, yr_str] or 0)
                u["spending_schedule"] = ss

    # ── Run Model ─────────────────────────────────────────────────────────────
    st.markdown("---")
    c1,c2 = st.columns([3,1])
    with c1:
        if st.button("🚀 Run Economic Model – All Units", type="primary", use_container_width=True):
            proj2 = P()
            all_res = []
            ws_list = st.session_state.get("well_schedule",[])
            with st.spinner("Computing cashflows for all units..."):
                for i, u in enumerate(proj2["units"]):
                    # Merge project-level (shared) params into unit params
                    run_p = {}
                    # Shared from project
                    for k in ["hurdle_rate","cost_esc_rate","corp_tax_rate","vat",
                               "production_fee_pct","production_bonus_pct","base_idr_usd",
                               "dep_years_wells","dep_years_pp","tax_loss_carryforward_yrs",
                               "exp_loan_principal","exp_loan_start_year","exp_loan_repay_years",
                               "exp_loan_grace_period","exp_loan_interest_rate",
                               "exp_loan_front_end_fee","exp_loan_commitment_fee",
                               "dev_upstream_loan_principal","dev_upstream_loan_start_year",
                               "dev_upstream_repay_years","dev_upstream_grace_period",
                               "dev_upstream_interest_rate","dev_upstream_front_end_fee",
                               "dev_upstream_commitment_fee",
                               "dev_downstream_loan_principal","dev_downstream_loan_start_year",
                               "dev_downstream_repay_years","dev_downstream_grace_period",
                               "dev_downstream_interest_rate","dev_downstream_front_end_fee",
                               "dev_downstream_commitment_fee",
                               "ga_exploration","survey_4g","land_infra_exploration",
                               "exploration_well_cost","n_exploration_wells"]:
                        if proj2.get(k) is not None:
                            run_p[k] = proj2[k]
                    # Unit-specific
                    run_p.update({k:v for k,v in u.items() if v is not None})
                    # Model horizon
                    run_p["start_year"]    = int(proj2.get("start_year") or 2026)
                    run_p["model_horizon"] = int(proj2.get("model_horizon") or 40)
                    # COD
                    cod_d = run_p.get("cod_date")
                    if isinstance(cod_d,str):
                        try: cod_d=date.fromisoformat(cod_d)
                        except: cod_d=None
                    if isinstance(cod_d,date):
                        run_p["cod_year"]=cod_d.year; run_p["cod_month"]=cod_d.month
                    else:
                        run_p.setdefault("cod_year", run_p["start_year"]+5)
                        run_p.setdefault("cod_month",1)
                    # CF/decline conversions
                    for pk,pv in [("capacity_factor",0.9),("production_decline",0.03),
                                  ("tariff_esc_rate",0.02355),("cost_esc_rate",0.02355),
                                  ("hurdle_rate",0.076),("corp_tax_rate",0.22),
                                  ("production_fee_pct",0.025),("production_bonus_pct",0.005),
                                  ("vat",0.11)]:
                        v = run_p.get(pk)
                        if v is None: run_p[pk]=pv
                        elif float(v)>1: run_p[pk]=float(v)/100
                    # Defaults for missing
                    DEFS = {"install_capacity":50,"lifetime":30,"initial_steam_supply":35,
                            "elec_fee_1_10":10.35,"elec_fee_11_30":8.0,
                            "steam_price_1_10":6.875,"steam_price_11_30":5.31,
                            "conv_fee_1_10":3.475,"conv_fee_11_30":2.69,
                            "n_prod_wells":3,"n_inj_wells":4,"n_makeup_wells":6,
                            "prod_well_cost":6000,"inj_well_cost":7095,
                            "makeup_well_cost":6801,"infra_makeup":16700,
                            "fcrs_cost":32612,"power_plant_cost":94366,
                            "feed_cost":500,"transmission_cost":2176,"idc":18604,
                            "ga_exploitation":1408,"dev_years_ga":5,
                            "land_infra_exploitation":3000,
                            "om_steam_annual":1760,"om_plant_annual":3970,
                            "major_overhaul_cost":2250,"major_overhaul_interval":5,
                            "minor_overhaul_cost":700,"minor_overhaul_interval":2,
                            "chemical_treatment":1000,"opex_transmission":36,
                            "pbb_annual":0,"dep_years_wells":20,"dep_years_pp":25}
                    for dk,dv in DEFS.items():
                        run_p.setdefault(dk,dv)
                    run_p["well_schedule"] = [w for w in ws_list
                                              if w.get("unit")==(u.get("unit_name") or f"Unit {i+1}")]
                    try:
                        all_res.append(run_model(run_p))
                    except Exception as e:
                        st.error(f"❌ {u.get('unit_name','Unit '+str(i+1))}: {e}")
                        all_res.append(None)
            st.session_state["results"] = [r for r in all_res if r]
            st.success(f"✅ {len(st.session_state['results'])} unit(s) computed! → 📊 Results Dashboard")
    with c2:
        if st.button("💾 Save Project",use_container_width=True):
            save_project(P()); st.success("Saved!")


