# PAGE: RESULTS DASHBOARD
# ══════════════════════════════════════════════════════════════════════════════
def page_dashboard():
    all_res = st.session_state.get("results",[])
    if not all_res:
        st.info("⚠️ Run the model first on **⚙️ Input Parameters** page."); return
    p2 = P(); units = p2.get("units",[])

    # ── Portfolio KPIs ─────────────────────────────────────────────────────────
    tnpv  = sum(r.get("npv_ufcf",0) for r in all_res)
    tcap  = sum(float(units[i].get("install_capacity") or 0) for i in range(len(all_res)) if i<len(units))
    tcapx = sum(r.get("total_capex",0) for r in all_res)
    tgen  = sum(r.get("total_gen_gwh",0) for r in all_res)
    virrs = [r.get("irr_ufcf") for r in all_res if r.get("irr_ufcf")]
    avgirr= np.mean(virrs)*100 if virrs else 0

    st.markdown(f"""
    <div class="kpi-row">
      <div class="kpi"><p class="kpi-lbl">Portfolio Capacity</p>
        <p class="kpi-val">{tcap:.0f} MW</p><p class="kpi-sub">{len(all_res)} unit(s)</p></div>
      <div class="kpi g"><p class="kpi-lbl">NPV UFCF</p>
        <p class="kpi-val" style="color:{'#22543d' if tnpv>0 else '#742a2a'}">{tnpv/1000:,.1f} M</p>
        <p class="kpi-sub">USD</p></div>
      <div class="kpi t"><p class="kpi-lbl">Avg IRR UFCF</p>
        <p class="kpi-val">{avgirr:.2f}%</p><p class="kpi-sub">All units</p></div>
      <div class="kpi o"><p class="kpi-lbl">Total CAPEX</p>
        <p class="kpi-val">{tcapx/1000:,.1f} M</p><p class="kpi-sub">USD</p></div>
      <div class="kpi p"><p class="kpi-lbl">Net Generation</p>
        <p class="kpi-val">{tgen:,.0f}</p><p class="kpi-sub">GWh lifetime</p></div>
    </div>""", unsafe_allow_html=True)

    # ── Comparison table ───────────────────────────────────────────────────────
    st.markdown('<div class="sec">📊 Economic Indicators – All Units</div>', unsafe_allow_html=True)
    rows=[]
    for i,res in enumerate(all_res):
        u=units[i] if i<len(units) else {}
        hr=float(u.get("hurdle_rate") or 0.076)
        irr_u=res.get("irr_ufcf"); irr_l=res.get("irr_lfcf")
        npv_u=res.get("npv_ufcf",0); npv_l=res.get("npv_lfcf",0)
        verd=("✅ Viable" if npv_u>0 and irr_u and irr_u>hr
              else "⚠️ Marginal" if npv_u>-50000 else "❌ Not Viable")
        rows.append({"Unit":u.get("unit_name",f"Unit {i+1}"),
            "Scheme":u.get("scheme","—"),"Cap (MW)":u.get("install_capacity","—"),
            "COD":str(u.get("cod_date","—")),
            "NPV UFCF (M)":round(npv_u/1000,1),"IRR UFCF (%)":round(irr_u*100,2) if irr_u else None,
            "NPV LFCF (M)":round(npv_l/1000,1),"IRR LFCF (%)":round(irr_l*100,2) if irr_l else None,
            "Payback (yr)":res.get("payback"),"D.PB (yr)":res.get("disc_payback"),
            "LCOE (¢/kWh)":round(res.get("lcoe",0),2),"Verdict":verd})
    st.dataframe(pd.DataFrame(rows),use_container_width=True,hide_index=True)

    # ── Per-unit detail tabs ───────────────────────────────────────────────────
    st.markdown('<div class="sec">🔍 Unit Detail</div>', unsafe_allow_html=True)
    unit_names=[units[i].get("unit_name",f"Unit {i+1}") if i<len(units) else f"Unit {i+1}" for i in range(len(all_res))]
    unit_tabs=st.tabs([f"⚡ {n}" for n in unit_names])

    for i,(res,tab) in enumerate(zip(all_res,unit_tabs)):
        with tab:
            u=units[i] if i<len(units) else {}
            years=res["years"]
            sub1,sub2=st.tabs(["📋 Full Cash Flow Table","📈 Charts"])

            with sub1:
                # Build comprehensive cashflow table per Excel format
                CF_ROWS=[
                    ("","","sec"),
                    ("WELL COUNT","","sec"),
                    ("Net Generation","net_gen","MWh"),
                    ("","",""),
                    ("Gross Revenue","revenue","kUSD"),
                    ("","","sec"),
                    ("CAPEX (Total)","capex","kUSD"),
                    ("","",""),
                    ("OPEX (Total)","opex","kUSD"),
                    ("","","sec"),
                    ("EBITDA","ebitda","kUSD"),
                    ("  Revenue","revenue","kUSD"),
                    ("  O&M Costs","opex","kUSD_neg"),
                    ("","",""),
                    ("Depreciation","depreciation","kUSD"),
                    ("EBIT (After-Tax)","ebit","kUSD"),
                    ("  EBT","ebt","kUSD"),
                    ("  Income Tax","income_tax","kUSD"),
                    ("","",""),
                    ("UFCF (Unlevered FCF)","ufcf","kUSD"),
                    ("  Add: Depreciation","depreciation","kUSD"),
                    ("  Less: CAPEX","capex","kUSD_neg"),
                    ("  Cum. UFCF","cum_ufcf","kUSD"),
                    ("","",""),
                    ("Discounted UFCF","disc_ufcf","kUSD"),
                    ("  Discounted Cum. UFCF","cum_disc_ufcf","kUSD"),
                    ("  Discount Factor","disc_factor","factor"),
                    ("","",""),
                    ("Interest Expense","interest","kUSD"),
                    ("Debt Repayment","debt_repay","kUSD"),
                    ("LFCF (Levered FCF)","lfcf","kUSD"),
                    ("  Cum. LFCF","cum_lfcf","kUSD"),
                    ("","",""),
                    ("Discounted LFCF","disc_lfcf","kUSD"),
                    ("  Discounted Cum. LFCF","cum_disc_lfcf","kUSD"),
                    ("","",""),
                    ("LCOE","","kUSD"),
                    ("  Undiscounted Production","net_gen","MWh"),
                ]

                # Build dataframe
                df_rows=[]
                for lbl,key,dtype in CF_ROWS:
                    if dtype=="sec":
                        row_d={"Parameter":f"▌ {lbl}" if lbl else "","Unit":""}
