    # Portfolio combined
    if len(all_res)>1:
        st.markdown('<div class="sec">🌐 Portfolio Combined Cash Flow</div>', unsafe_allow_html=True)
        yr0=all_res[0]["years"]
        port_u=[sum(r["ufcf"].get(y,0) for r in all_res)/1000 for y in yr0]
        port_cu=np.cumsum(port_u).tolist()
        figp=make_subplots(specs=[[{"secondary_y":True}]])
